import{_ as a}from"./chunks/Audio.COine8Wh.js";import{_ as r}from"./chunks/Tags.BJ536pW3.js";import{c as s,o as n,j as t,G as i,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const b=JSON.parse('{"title":"Veteran Fraud Reimbursement Act of 2025","description":"","frontmatter":{"legisId":"2025-12-12-veteran-fraud-reimbursement-act-of-2025","title":"Veteran Fraud Reimbursement Act of 2025","displayTitle":"Veteran Fraud Reimbursement Act of 2025","lawNumber":"119-56","billNumber":"H.R. 1912","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ56.xml","publishDate":"2025-12-12T00:00:00-05:00","industries":["finance","government-operations"],"agencies":["Department of Veterans Affairs"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Veteran Fraud Reimbursement Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-veteran-fraud-reimbursement-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Veteran Fraud Reimbursement Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-veteran-fraud-reimbursement-act-of-2025\\",\\"datePublished\\":\\"2025-12-12T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-12-veteran-fraud-reimbursement-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-12-veteran-fraud-reimbursement-act-of-2025.md","filePath":"congress-bills/2025-12-12-veteran-fraud-reimbursement-act-of-2025.md","lastUpdated":1788887623000}'),u={name:"congress-bills/2025-12-12-veteran-fraud-reimbursement-act-of-2025.md"},h=Object.assign(u,{setup(f){return(m,e)=>(n(),s("div",null,[e[0]||(e[0]=t("h1",{id:"veteran-fraud-reimbursement-act-of-2025",tabindex:"-1"},[l("Veteran Fraud Reimbursement Act of 2025 "),t("a",{class:"header-anchor",href:"#veteran-fraud-reimbursement-act-of-2025","aria-label":'Permalink to "Veteran Fraud Reimbursement Act of 2025"'},"​")],-1)),i(a),i(r,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Friday, December 12, 2025. Public Law 119-56, H.R. 1912.</p><p><strong>Headline:</strong> The law requires the Department of Veterans Affairs to promptly replace benefits misused by a fiduciary.</p><p><strong>Why it matters:</strong> Veterans and other beneficiaries no longer have to wait for a VA negligence review before receiving replacement funds.</p><p><strong>What the law does:</strong></p><ul><li>Requires the VA to repay the beneficiary or successor fiduciary for benefits misused by a fiduciary.</li><li>Directs the VA to make a good faith effort to recover the money from the responsible fiduciary.</li><li>Requires recovered funds not already replaced to be promptly paid to the beneficiary or successor fiduciary.</li><li>Establishes payment procedures when a beneficiary dies and bars payment to the fiduciary who misused the benefits.</li><li>Caps total payments at the amount of benefits misused.</li><li>Requires VA negligence-assessment procedures without allowing a pending assessment to delay repayment.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Veterans and other VA beneficiaries whose benefits were misused.</li><li>Successor fiduciaries and eligible recipients after a beneficiary’s death.</li><li>Fiduciaries responsible for misusing VA benefits.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>An affected beneficiary can receive replacement benefits without waiting for the VA to determine whether it was negligent.</li><li>If the beneficiary dies before payment, an eligible person or entity may receive the money instead of the fiduciary responsible for the misuse.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="veteran-fraud-reimbursement-act-of-2025-1" tabindex="-1">Veteran Fraud Reimbursement Act of 2025 <a class="header-anchor" href="#veteran-fraud-reimbursement-act-of-2025-1" aria-label="Permalink to &quot;Veteran Fraud Reimbursement Act of 2025&quot;">​</a></h3><p>This law requires the Department of Veterans Affairs to replace benefits misused by a fiduciary and to try in good faith to recover the money from that fiduciary. It also establishes payment rules when the beneficiary has died and prevents negligence reviews from delaying replacement payments.</p><p><strong>Key takeaways:</strong></p><ul><li>The VA must repay a beneficiary or successor fiduciary an amount equal to the benefits misused by a fiduciary.</li><li>The VA must make a good faith effort to recover misused funds from the responsible fiduciary.</li><li>Any recovered money not already replaced must be promptly paid to the beneficiary or successor fiduciary.</li><li>If the beneficiary dies before payment, the VA must pay an eligible person or entity, but cannot pay the fiduciary who misused the benefits.</li><li>Total payments cannot exceed the amount of benefits that was misused.</li><li>The VA must establish procedures for assessing its own negligence, but a pending assessment cannot delay repayment.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ56.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ56.xml</a></p>',15))]))}});export{b as __pageData,h as default};
